set -euo pipefail
upload_dir=$(getent passwd "$SUDO_USER" | cut -d: -f6)
cd /opt/news-flow/current
/opt/news-flow/node/bin/node --input-type=module - <<'NODE'
import fs from 'node:fs';import assert from 'node:assert/strict';import {createHash} from 'node:crypto';import {createRequire} from 'node:module';import {DatabaseSync} from 'node:sqlite';import {cnnLitePublicAccessProofMatches} from './src/web/newsCnnLite.mjs';const root='/var/lib/news-flow/qc-public24-20261123',require=createRequire('/opt/news-flow/current/package.json'),env=require('dotenv').parse(fs.readFileSync('/etc/news-flow/news.env')),ES=require('elasticsearch'),es=new ES.Client({host:env.ES5_HOST,apiVersion:'5.6',log:[],maxRetries:0,requestTimeout:15000}),db=new DatabaseSync('/var/lib/news-flow/news-flow-runtime/write.sqlite',{readOnly:true}),post=JSON.parse(fs.readFileSync(root+'/postcheck.json')),description=JSON.parse(fs.readFileSync(root+'/description-reconciliation.json')),native=JSON.parse(fs.readFileSync(root+'/native-es-readback.json')),heading=JSON.parse(fs.readFileSync(root+'/cnn-heading-recovery.json')),manifest=JSON.parse(fs.readFileSync(root+'/cnn-helper-manifest.json')),apply=JSON.parse(fs.readFileSync('/var/lib/news-flow/qc-recover25-20261122/cnn-apply-result.json')),from=Date.parse(apply.at),rows=db.prepare("SELECT * FROM import_receipts WHERE imported_at>=? AND url LIKE '%cnn.com/%' ORDER BY imported_at,id").all(from),events=db.prepare("SELECT details FROM events WHERE site='edition.cnn.com' AND kind='verified' AND at>=?").all(from),byId=new Map(events.map(e=>{const v=JSON.parse(e.details);return [v.id,v];})),r={at:new Date().toISOString(),postcheckVerified:post.verified,tieudungsoNativeReadbacks:native.tieudungso.length,tieudungsoDescriptionReconciled:description.combinedVerified,cnnReadbacks:[],agePolicy:'all_history_matches_production',manualAiCalls:0,aiUsage:db.prepare('SELECT * FROM ai_usage ORDER BY day').all(),moduleSha256:createHash('sha256').update(fs.readFileSync(manifest.path)).digest('hex')};
try{const info=await es.info(),proof=JSON.parse(fs.readFileSync('/etc/news-flow/identity-proof.json')).summary;assert(proof.verified&&info.version.number.startsWith('5.6.')&&createHash('sha256').update(info.cluster_uuid).digest('hex')===proof.clusterFingerprint);for(let i=0;i<rows.length;i+=50){const batch=rows.slice(i,i+50),response=await es.mget({body:{docs:batch.map(s=>({_index:s.es_index,_type:s.es_type,_id:s.es_id}))}});for(let j=0;j<batch.length;j++){const row=batch[j],doc=response.docs[j],event=byId.get(row.id);r.cnnReadbacks.push({url:row.url,id:row.id,receiptStatus:row.status,found:doc.found===true,proofMatched:doc.found===true&&cnnLitePublicAccessProofMatches(doc._source,event?.publicAccessProof),descriptionPresent:!!doc._source?.description,publishedDate:doc._source?.publishedDate});}}
const receipt=db.prepare('SELECT * FROM import_receipts WHERE id=?').get(heading.writtenDoc._id);assert(receipt);const hit=await es.get({index:receipt.es_index,type:receipt.es_type,id:receipt.es_id});r.cnnHeadingExactFields=['url','title','content','description','publishedDate'].every(k=>JSON.stringify(hit._source[k])===JSON.stringify(heading.writtenDoc._source[k]));r.verified=r.postcheckVerified&&r.tieudungsoDescriptionReconciled&&r.tieudungsoNativeReadbacks===14&&r.moduleSha256===manifest.afterSha&&r.cnnReadbacks.length>=103&&r.cnnReadbacks.every(p=>p.found&&p.proofMatched&&p.descriptionPresent)&&r.cnnHeadingExactFields;fs.writeFileSync(root+'/final-verification.json',JSON.stringify(r,null,2));assert(r.verified);console.log(JSON.stringify({verified:r.verified,tieudungso:r.tieudungsoNativeReadbacks,cnn:r.cnnReadbacks.length,cnnHeadingExactFields:r.cnnHeadingExactFields,moduleSha256:r.moduleSha256,manualAiCalls:0,latestAiUsage:r.aiUsage.at(-1)}));}finally{db.close();es.close();}
NODE
for name in postcheck final-verification age-policy age-correction native-es-readback description-reconciliation cnn-helper-manifest cnn-heading-recovery deployed-tieudungso last-routes; do install -o "$SUDO_USER" -m 0600 "/var/lib/news-flow/qc-public24-20261123/$name.json" "$upload_dir/.qc-public24-$name.json"; done
